import java.util.Scanner;

public class Main {
    static final long MOD_CONST = 1000000007;

    static long getInput(Scanner sc) {
        long num = 0;
        boolean negative = false;
        char c = sc.next().charAt(0);
        while (c != '-' && (c < '0' || c > '9')) {
            c = sc.next().charAt(0);
        }
        if (c == '-') {
            negative = true;
            c = sc.next().charAt(0);
        }
        num = c - '0';
        while (true) {
            if (!sc.hasNext()) break;
            c = sc.next().charAt(0);
            if (c < '0' || c > '9') break;
            num = num * 10 + (c - '0');
        }
        return negative ? -num : num;
    }

    static long modMultiply(long a, long b, long m) {
        long res = 0;
        a %= m;
        while (b > 0) {
            if ((b & 1) == 1) {
                res = (res + a) % m;
            }
            a = (a + a) % m;
            b >>= 1;
        }
        return res;
    }

    static long modPower(long base, long exp, long m) {
        long ans = 1;
        base %= m;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                ans = modMultiply(ans, base, m);
            }
            base = modMultiply(base, base, m);
            exp >>= 1;
        }
        return ans;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p_value = getInput(sc);
        long k_value = getInput(sc);
        long result;
        if (k_value == 0) {
            result = modPower(p_value, p_value - 1, MOD_CONST);
        } else if (k_value == 1) {
            result = modPower(p_value, p_value, MOD_CONST);
        } else {
            long cycle_length = 1;
            long current = k_value;
            while (current != 1) {
                current = (current * k_value) % p_value;
                cycle_length++;
            }
            result = modPower(p_value, (p_value - 1) / cycle_length, MOD_CONST);
        }
        System.out.println(result);
        sc.close();
    }
}
